import React, { ElementRef, useContext, useRef } from 'react';
import type { CSSObject } from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

import {
  baseLegendButton,
  legendItem,
  legendItemButton,
  legendNameButton,
  legendNameButtonOverride,
  legendNameWrapper,
} from './ChartLegendItem.sty.js';
import { useFocusRing } from '../../../../../../../core/hooks/useFocusRing.js';
import { Tooltip } from '../../../../../../../overlays/tooltip/Tooltip.js';
import { TextEllipsis } from '../../../../../../../typography/TextEllipsis.js';
import { DEFAULT_TRUNCATION_MODE } from '../../../../../constants.js';
import { LegendContext } from '../../../shared/context/Legend.context.js';
import { useLegendGridSettings } from '../../context/LegendGridSettingsContext.js';
import { useLegendItemActions } from '../../hooks/useLegendItemActions.js';
import { useLegendItemInteractions } from '../../hooks/useLegendItemInteractions.js';
import { useLegendItemState } from '../../hooks/useLegendItemState.js';
import { useLegendItemTruncation } from '../../hooks/useLegendItemTruncation.js';
import { LEGEND_MESSAGES } from '../../messages.js';
import { LegendItem } from '../../types/legend.js';
import { ChartLegendIcon } from '../ChartLegendIcon/ChartLegendIcon.js';
import { ChartLegendSeriesActions } from '../ChartLegendSeriesActions.js';

interface ChartLegendItemProps {
  item: LegendItem;
  active?: HTMLElement;
  numberOfItems: number;
}

const MAX_WIDTH_GAP = 15;

export const ChartLegendItem = (props: ChartLegendItemProps) => {
  const { item, numberOfItems } = props;
  const { maxItemWidth } = useLegendGridSettings();

  const textRef = useRef<ElementRef<'span'>>(null);

  const isTruncated = useLegendItemTruncation(textRef, item.name);

  const {
    hiddenItems,
    truncationMode,
    onLegendIconClick,
    onItemHover,
    onLegendNameClick,
    interactionsDisabled,
    onSeriesAction: actions,
  } = useContext(LegendContext);

  const {
    refIconButton,
    refNameButton,
    open,
    updateOpenState,
    updateHoveredState,
    updateVisible,
    visible,
    isLastItem,
    shouldShowActionsButton,
    isIconHovered,
  } = useLegendItemState(
    item,
    interactionsDisabled,
    hiddenItems,
    numberOfItems,
  );

  const { intl, defaultActions } = useLegendItemActions(item);

  const ariaDisabled = isLastItem ? { 'aria-disabled': true } : undefined;

  const {
    handleLabelMouseEnter,
    handleIconMouseEnter,
    handleMouseLeave,
    onNameButtonClick,
    onNameButtonKeyDown,
    onIconButtonClick,
  } = useLegendItemInteractions(
    item,
    {
      onItemHover,
      onLegendIconClick,
      onLegendNameClick,
      updateHoveredState,
      updateVisible,
      visible,
    },
    interactionsDisabled,
  );

  const iconButtonClickHandler = !isLastItem ? onIconButtonClick : undefined;
  const disabled = interactionsDisabled || isLastItem;

  const {
    focusProps: nameButtonFocusProps,
    focusStyles: nameButtonFocusStyles,
  } = useFocusRing();
  const {
    focusProps: iconButtonFocusProps,
    focusStyles: iconButtonFocusStyles,
  } = useFocusRing();

  return (
    <div
      onMouseLeave={handleMouseLeave}
      data-testid="chart-legend-item"
      className={legendItem}
    >
      <Tooltip
        data-testid={
          disabled
            ? 'chart-legend-item-tooltip-disabled'
            : 'chart-legend-item-tooltip'
        }
        disabled={disabled}
        text={
          visible
            ? intl.formatMessage(LEGEND_MESSAGES.legendHideSeries)
            : intl.formatMessage(LEGEND_MESSAGES.legendShowSeries)
        }
        placement={'left'}
      >
        <button
          ref={refIconButton}
          data-testid="chart-legend-item-icon"
          disabled={disabled}
          onFocus={(e) => {
            iconButtonFocusProps.onFocus(e);
            handleIconMouseEnter();
          }}
          onClick={iconButtonClickHandler}
          onBlur={(event) => {
            iconButtonFocusProps.onBlur(event);
          }}
          onMouseEnter={handleIconMouseEnter}
          {...ariaDisabled}
          className={`${baseLegendButton} ${legendItemButton({
            isInteractive: !interactionsDisabled,
          })}`}
          style={{
            ...(iconButtonFocusStyles as CSSObject),
            color:
              visible || isIconHovered
                ? item.color.Default
                : Colors.Text.Neutral.Subdued,
          }}
        >
          <ChartLegendIcon
            visible={visible}
            hover={isIconHovered}
            disabled={isLastItem}
            color={item.color.Default}
            icon={item.icon}
          />
        </button>
      </Tooltip>
      <div
        onMouseEnter={handleLabelMouseEnter}
        onFocus={handleLabelMouseEnter}
        data-testid="chart-legend-name-wrapper"
        className={legendNameWrapper}
      >
        <Tooltip text={item.name} disabled={!isTruncated}>
          <button
            data-testid="chart-legend-item-name"
            ref={refNameButton}
            onClick={(evt) => onNameButtonClick(evt.nativeEvent)}
            onKeyDown={(evt) => onNameButtonKeyDown(evt.nativeEvent)}
            tabIndex={interactionsDisabled ? -1 : 0}
            {...nameButtonFocusProps}
            className={`${baseLegendButton} ${legendNameButton({
              isInteractive: !interactionsDisabled,
              isSubdued: !visible,
            })} ${legendNameButtonOverride}`}
            style={{
              flexBasis: maxItemWidth + MAX_WIDTH_GAP,
              ...nameButtonFocusStyles,
            }}
          >
            <TextEllipsis
              truncationMode={truncationMode ?? DEFAULT_TRUNCATION_MODE}
              aria-label="Series name"
              ref={textRef}
            >
              {item.name}
            </TextEllipsis>
          </button>
        </Tooltip>
        {actions && shouldShowActionsButton && (
          <ChartLegendSeriesActions
            disabled={interactionsDisabled}
            visible={shouldShowActionsButton}
            onOpenChange={updateOpenState}
            isOpen={open}
            onFocus={handleLabelMouseEnter}
            onBlur={handleMouseLeave}
          >
            {defaultActions}
            {actions?.(item)?.props?.children}
          </ChartLegendSeriesActions>
        )}
      </div>
    </div>
  );
};

ChartLegendItem['displayName'] = 'ChartLegendItem';
